// See also: DestroyPalette, SetPaletteColors, SetSurfacePalette
func CreatePalette(ncolors int32) *Palette {
	return fnCreatePalette(ncolors)
}

var fnSetPaletteColors func(palette *Palette, colors *Color, firstcolor int32, ncolors int32) bool

// Set a range of colors in a palette.
//
// Parameters:
//   - palette: the Palette structure to modify.
//   - colors: an array of Color structures to copy into the palette.
//   - firstcolor: the index of the first palette entry to modify.
//   - ncolors: the number of entries to modify.
//
// Returns: true on success or false on failure; call GetError() for more information.
//
// Thread safety: It is safe to call this function from any thread, as long as the palette is not modified or destroyed in another thread.
//
// Since: SDL 3.2.0.
func SetPaletteColors(palette *Palette, colors *Color, firstcolor int32, ncolors int32) bool {
	return fnSetPaletteColors(palette, colors, firstcolor, ncolors)
}

var fnDestroyPalette func(palette *Palette)

// Free a palette created with CreatePalette().
//
// Parameters:
//   - palette: the Palette structure to be freed.
//
// Thread safety: It is safe to call this function from any thread, as long as the palette is not modified or destroyed in another thread.
//
// Since: SDL 3.2.0.
//
// See also: CreatePalette
func DestroyPalette(palette *Palette) {
	fnDestroyPalette(palette)
}

var fnMapRGB func(format *PixelFormatDetails, palette *Palette, r uint8, g uint8, b uint8) uint32

// Map an RGB triple to an opaque pixel value for a given pixel format.
//
// This function maps the RGB color value to the specified pixel format and
// returns the pixel value best approximating the given RGB color value for
// the given pixel format.
//
// If the format has a palette (8-bit) the index of the closest matching color
// in the palette will be returned.
//
// If the specified pixel format has an alpha component it will be returned as
// all 1 bits (fully opaque).
//
// If the pixel format bpp (color depth) is less than 32-bpp then the unused
// upper bits of the return value can safely be ignored (e.g., with a 16-bpp
// format the return value can be assigned to a Uint16, and similarly a Uint8
// for an 8-bpp format).
//
// Parameters:
//   - format: a pointer to PixelFormatDetails describing the pixel format.
//   - palette: an optional palette for indexed formats, may be NULL.
//   - r: the red component of the pixel in the range 0-255.
//   - g: the green component of the pixel in the range 0-255.
//   - b: the blue component of the pixel in the range 0-255.
//
// Returns: a pixel value.
//
// Thread safety: It is safe to call this function from any thread, as long as the palette is not modified.
//
// Since: SDL 3.2.0.
//
// See also: GetPixelFormatDetails, GetRGB, MapRGBA, MapSurfaceRGB
func MapRGB(format *PixelFormatDetails, palette *Palette, r uint8, g uint8, b uint8) uint32 {
	return fnMapRGB(format, palette, r, g, b)
}

var fnMapRGBA func(format *PixelFormatDetails, palette *Palette, r uint8, g uint8, b uint8, a uint8) uint32

// Map an RGBA quadruple to a pixel value for a given pixel format.
//
// This function maps the RGBA color value to the specified pixel format and
// returns the pixel value best approximating the given RGBA color value for
// the given pixel format.
//
// If the specified pixel format has no alpha component the alpha value will
// be ignored (as it will be in formats with a palette).
//
// If the format has a palette (8-bit) the index of the closest matching color
// in the palette will be returned.
//
// If the pixel format bpp (color depth) is less than 32-bpp then the unused
// upper bits of the return value can safely be ignored (e.g., with a 16-bpp
// format the return value can be assigned to a Uint16, and similarly a Uint8
// for an 8-bpp format).
//
// Parameters:
//   - format: a pointer to PixelFormatDetails describing the pixel format.
//   - palette: an optional palette for indexed formats, may be NULL.
//   - r: the red component of the pixel in the range 0-255.
//   - g: the green component of the pixel in the range 0-255.
//   - b: the blue component of the pixel in the range 0-255.
//   - a: the alpha component of the pixel in the range 0-255.
//
// Returns: a pixel value.
//
// Thread safety: It is safe to call this function from any thread, as long as the palette is not modified.
//
// Since: SDL 3.2.0.
//
// See also: GetPixelFormatDetails, GetRGBA, MapRGB, MapSurfaceRGBA
func MapRGBA(format *PixelFormatDetails, palette *Palette, r uint8, g uint8, b uint8, a uint8) uint32 {
	return fnMapRGBA(format, palette, r, g, b, a)
}

var fnGetRGB func(pixelvalue uint32, format *PixelFormatDetails, palette *Palette, r *uint8, g *uint8, b *uint8)

// Get RGB values from a pixel in the specified format.
//
// This function uses the entire 8-bit [0..255] range when converting color
// components from pixel formats with less than 8-bits per RGB component
// (e.g., a completely white pixel in 16-bit RGB565 format would return [0xff,
// 0xff, 0xff] not [0xf8, 0xfc, 0xf8]).
//
// Parameters:
//   - pixelvalue: a pixel value.
//   - format: a pointer to PixelFormatDetails describing the pixel format.
//   - palette: an optional palette for indexed formats, may be NULL.
//   - r: a pointer filled in with the red component, may be NULL.
//   - g: a pointer filled in with the green component, may be NULL.
//   - b: a pointer filled in with the blue component, may be NULL.
//
// Thread safety: It is safe to call this function from any thread, as long as the palette is not modified.
//
// Since: SDL 3.2.0.
//
// See also: GetPixelFormatDetails, GetRGBA, MapRGB, MapRGBA
func GetRGB(pixelvalue uint32, format *PixelFormatDetails, palette *Palette, r *uint8, g *uint8, b *uint8) {
	fnGetRGB(pixelvalue, format, palette, r, g, b)
}

var fnGetRGBA func(pixelvalue uint32, format *PixelFormatDetails, palette *Palette, r *uint8, g *uint8, b *uint8, a *uint8)

// Get RGBA values from a pixel in the specified format.
//
// This function uses the entire 8-bit [0..255] range when converting color
// components from pixel formats with less than 8-bits per RGB component
// (e.g., a completely white pixel in 16-bit RGB565 format would return [0xff,
// 0xff, 0xff] not [0xf8, 0xfc, 0xf8]).
//
// If the surface has no alpha component, the alpha will be returned as 0xff
// (100% opaque).
//
// Parameters:
//   - pixelvalue: a pixel value.
//   - format: a pointer to PixelFormatDetails describing the pixel format.
//   - palette: an optional palette for indexed formats, may be NULL.
//   - r: a pointer filled in with the red component, may be NULL.
//   - g: a pointer filled in with the green component, may be NULL.
//   - b: a pointer filled in with the blue component, may be NULL.
//   - a: a pointer filled in with the alpha component, may be NULL.
//
// Thread safety: It is safe to call this function from any thread, as long as the palette is not modified.
//
// Since: SDL 3.2.0.
//
// See also: GetPixelFormatDetails, GetRGB, MapRGB, MapRGBA
func GetRGBA(pixelvalue uint32, format *PixelFormatDetails, palette *Palette, r *uint8, g *uint8, b *uint8, a *uint8) {
	fnGetRGBA(pixelvalue, format, palette, r, g, b, a)
}
